const ALPHABET="0123456789ABCDEFGHJKMNPQRSTVWXYZ";const CHECK_ALPHABET=ALPHABET+"*~$=U";export const KEY_BYTES=15;export const KEY_SYMBOLS=24;export const DESTROY_DOMAIN="tessera-destroy-v1:";export const COMMITMENT_BYTES=15;export function normalize(input){return String(input).toUpperCase().replace(/[\s-]/g,"").replace(/[IL]/g,"1").replace(/O/g,"0")}export function encode(bytes){let value=0;let bits=0;let out="";for(const byte of bytes){value=value<<8|byte;bits+=8;while(bits>=5){bits-=5;out+=ALPHABET[value>>>bits&31]}}return out}export function decode(symbols){let value=0;let bits=0;const bytes=[];for(const c of symbols){const v=ALPHABET.indexOf(c);if(v<0){throw new Error("crockford: invalid symbol")}value=value<<5|v;bits+=5;if(bits>=8){bits-=8;bytes.push(value>>>bits&255)}}return new Uint8Array(bytes)}export function checkSymbol(bytes){let rem=0;for(const byte of bytes){rem=(rem*256+byte)%37}return CHECK_ALPHABET[rem]}export function format(code){return code.match(/.{1,5}/g).join("-")}export function isValid(input){const code=normalize(input);if(code.length!==KEY_SYMBOLS+1){return false}try{return checkSymbol(decode(code.slice(0,KEY_SYMBOLS)))===code[KEY_SYMBOLS]}catch{return false}}export function generateKey(){if(typeof crypto==="undefined"||typeof crypto.getRandomValues!=="function"){throw new Error("crockford: no CSPRNG available, refusing to generate a key")}const bytes=crypto.getRandomValues(new Uint8Array(KEY_BYTES));return format(encode(bytes)+checkSymbol(bytes))}export async function commitment(input){if(typeof crypto==="undefined"||!crypto.subtle){throw new Error("crockford: crypto.subtle unavailable (needs a secure context)")}const message=new TextEncoder().encode(DESTROY_DOMAIN+normalize(input));const digest=await crypto.subtle.digest("SHA-256",message);return new Uint8Array(digest).slice(0,COMMITMENT_BYTES)}
